+  "mappings": {
+    "_source": { "mode": "synthetic" },
+    "properties": {
+      "my_range": { "type": "long_range" }
+    }
+  }
+}
+
+PUT idx/_doc/1
+{
+  "my_range": [
+    {
+        "gte": 200,
+        "lte": 300
+    },
+    {
+        "gte": 1,
+        "lte": 100
+    },
+    {
+        "gte": 200,
+        "lte": 300
+    },
+    {
+        "gte": 200,
+        "lte": 500
+    }
+  ]
+}
+----
+// TEST[s/$/\nGET idx\/_doc\/1?filter_path=_source\n/]
